export const COLOR_MAP = {
  'Late_Blight': '#e74c3c',
  'Bacterial_Spot': '#3498db',
  'Spider_Mites': '#f39c12',
  'Leaf_Mold': '#9b59b6',
  'Aphids': '#e67e22',
  'Cercospora': '#1abc9c',
  'Early_Blight': '#c0392b',
};

export const DEFAULT_HOTSPOTS = [
  { lat: 19.8, lng: 75.9, diseaseName: 'Late_Blight', severity: 1.0 },
  { lat: 21.1, lng: 79.1, diseaseName: 'Bacterial_Spot', severity: 0.85 },
  { lat: 18.7, lng: 74.2, diseaseName: 'Spider_Mites', severity: 0.7 },
  { lat: 20.5, lng: 77.3, diseaseName: 'Leaf_Mold', severity: 0.6 },
  { lat: 17.2, lng: 78.3, diseaseName: 'Aphids', severity: 0.9 },
  { lat: 16.8, lng: 73.7, diseaseName: 'Cercospora', severity: 0.5 },
  { lat: 19.3, lng: 76.5, diseaseName: 'Early_Blight', severity: 1.0 },
];

export function projectCoordinate(lat, lng) {
  const x = ((lng - BOUNDS.minLng) / (BOUNDS.maxLng - BOUNDS.minLng)) * VIEW_W;
  const y = VIEW_H - ((lat - BOUNDS.minLat) / (BOUNDS.maxLat - BOUNDS.minLat)) * VIEW_H;
  return { x, y };
}

export default function DiseaseHotspotMap({
  hotspots = DEFAULT_HOTSPOTS,
  farmerLocation = { lat: 19.1, lng: 74.7 },
  title = 'Maharashtra Disease Outbreak Radar',
  loading = false,
  onHotspotPress = (hotspot) => console.log('Selected Outbreak:', hotspot),
}) {
  const farmerPoint = farmerLocation ? projectCoordinate(farmerLocation.lat, farmerLocation.lng) : null;
  const list = hotspots || [];

  return (
    <View style={styles.container}>
      <Text style={styles.title} accessibilityRole="header">{title}</Text>

      {loading && (
        <ActivityIndicator size="large" color="#2980b9" style={styles.loader} />
      )}

      <Svg width="100%" height="100%" viewBox={`0 0 ${VIEW_W} ${VIEW_H}`}>

        <Defs>
          <ClipPath id="maharashtraMask">
            <Path d={MH_DISTRICT_OUTLINES} />
          </ClipPath>
        </Defs>

        <Path
          d={MH_DISTRICT_OUTLINES}
          fill="transparent"
          stroke="#34495e"
          strokeWidth="14.4"
        />

        <G clipPath="url(#maharashtraMask)">
          {list.map((h, i) => {
            const { x, y } = projectCoordinate(h.lat, h.lng);
            const r = 90 + (h.severity || 0.6) * 110;
            const color = COLOR_MAP[h.diseaseName] || '#e74c3c';

            return (
              <Pressable key={i} onPress={() => onHotspotPress(h)}>
                <Circle
                  cx={x}
                  cy={y}
                  r={r}
                  fill={color}
                  opacity={0.65}
                  accessibilityLabel={`${h.diseaseName} hotspot, severity ${h.severity}`}
                  accessibilityRole="button"
                />
              </Pressable>
            );
          })}
        </G>

        {farmerPoint && (
          <G>
            <Circle cx={farmerPoint.x} cy={farmerPoint.y} r={160} fill="#2980b9" opacity={0.3} />
            <Circle cx={farmerPoint.x} cy={farmerPoint.y} r={60} fill="#2980b9" stroke="#ffffff" strokeWidth={12} />
          </G>
        )}
      </Svg>
    </View>
  );
}

const styles = StyleSheet.create({
  container: {
    width: '100%',
    aspectRatio: 7200 / 8100,
    alignItems: 'center',
    justifyContent: 'center',
    padding: 8,
  },
  title: {
    fontSize: 14,
    fontWeight: '600',
    marginBottom: 6,
    color: '#2c3e50',
  },
  loader: {
    position: 'absolute',
    top: 40,
  },
});